    const m = mergeWeighIns([{ date: "2026-01-01", kg: 80, source: "hevy" }, { date: "2026-01-01", kg: 81, source: "hevy" }, { date: "2026-01-01", kg: 90, source: "manual" }], { priority: ["hevy", "manual", "whoop"] });
